import type { WidgetContext, WidgetFieldValue, WidgetQueryResult } from "../_lib/widget_context";

// Who's on a Minecraft Bedrock server. The card folds back to the plain one while nobody is on.
//
// Bedrock Dedicated Server logs "Player connected: <name>, xuid: ..." and "Player disconnected:
// <name>, xuid: ..." to its console, which is the container's output: read over the Docker socket
// the HexOS container has, from when the container last started, since a restart starts the world
// with nobody on. The server's name and limit are the image's SERVER_NAME and MAX_PLAYERS. A box
// without the socket keeps the plain card.

const DOCKER_SOCKET = "/var/run/docker.sock";
/** Under the widget's 5 s timeout, so a stuck daemon reads as nobody on rather than failing the card. */
const DOCKER_TIMEOUT_MS = 2000;
/** Enough of a long session's output to hold every join and leave since the server started. */
const LOG_LINES = 5000;

async function docker(path: string): Promise<Response | null> {
  try {
    const response = await fetch(`http://docker${path}`, { unix: DOCKER_SOCKET, signal: AbortSignal.timeout(DOCKER_TIMEOUT_MS) });
    return response.ok ? response : null;
  } catch {
    return null; // a box with no socket yet
  }
}

interface Container {
  Id: string;
  State?: { StartedAt?: string };
  Config?: { Env?: string[]; Cmd?: string[] };
}

/** The app's running container, by compose project, since a later copy's is ix-<app>-2-<service>-1. */
async function containerOf(appId: string): Promise<Container | null> {
  const filters = encodeURIComponent(JSON.stringify({ label: [`com.docker.compose.project=ix-${appId}`], status: ["running"] }));
  const listed = (await (await docker(`/containers/json?filters=${filters}`))?.json().catch(() => null)) as Array<{ Id: string }> | null;
  const id = listed?.[0]?.Id;
  if (!id) return null;
  return ((await (await docker(`/containers/${id}/json`))?.json().catch(() => null)) as Container | null) ?? null;
}

/** A container's environment as a map. */
export const envOf = (container: Container | null): Map<string, string> =>
  new Map((container?.Config?.Env ?? []).map((pair) => [pair.slice(0, pair.indexOf("=")), pair.slice(pair.indexOf("=") + 1)]));

/**
 * Docker's log stream as text: a container without a terminal frames each chunk with an 8-byte
 * header (stream, three zeros, length), one with a terminal sends it as it is.
 */
export function demux(bytes: Uint8Array): string {
  const framed = bytes.length >= 8 && bytes[0] <= 2 && bytes[1] === 0 && bytes[2] === 0 && bytes[3] === 0;
  if (!framed) return new TextDecoder().decode(bytes);
  const parts: Uint8Array[] = [];
  for (let at = 0; at + 8 <= bytes.length; ) {
    const size = ((bytes[at + 4] << 24) | (bytes[at + 5] << 16) | (bytes[at + 6] << 8) | bytes[at + 7]) >>> 0;
    parts.push(bytes.subarray(at + 8, at + 8 + size));
    at += 8 + size;
  }
  return parts.map((part) => new TextDecoder().decode(part)).join("");
}

/** Terminal colours and title codes, and carriage returns, out of a console's lines. */
export const plainLines = (text: string): string[] =>
  text
    .replace(/\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[=>]/g, "")
    .split(/\r?\n|\r/)
    .map((line) => line.trim())
    .filter(Boolean);

/** The container's output since it last started: a restart starts a new session with nobody on. */
async function sessionLog(container: Container): Promise<string[]> {
  const started = Date.parse(container.State?.StartedAt ?? "");
  const since = Number.isFinite(started) ? Math.floor(started / 1000) : 0;
  const response = await docker(`/containers/${container.Id}/logs?stdout=true&stderr=true&since=${since}&tail=${LOG_LINES}`);
  return response ? plainLines(demux(new Uint8Array(await response.arrayBuffer()))) : [];
}

/** Who's online in a line: "Alex, Steve, and 3 more". */
export function playersLine(names: string[]): string {
  if (names.length <= 2) return names.join(" and ");
  if (names.length === 3) return `${names[0]}, ${names[1]}, and ${names[2]}`;
  return `${names[0]}, ${names[1]}, and ${names.length - 2} more`;
}

const CONNECTED = /Player connected: (.+?), xuid/;
const DISCONNECTED = /Player disconnected: (.+?), xuid/;

/** Who's on, in the order they connected, from the console's lines since the server started. */
export function sessionPlayers(lines: string[]): string[] {
  const online = new Set<string>();
  for (const line of lines) {
    const joined = CONNECTED.exec(line);
    if (joined) {
      online.add(joined[1]);
      continue;
    }
    const left = DISCONNECTED.exec(line);
    if (left) online.delete(left[1]);
  }
  return [...online];
}

export async function run(ctx: WidgetContext): Promise<WidgetQueryResult> {
  const container = await containerOf(ctx.appId);
  const names = container ? sessionPlayers(await sessionLog(container)) : [];
  const env = envOf(container);
  const max = Number(env.get("MAX_PLAYERS")) || 10;
  const fields: Record<string, WidgetFieldValue> = {
    // One entry while anyone's on: the server's name in bold, the players in the small line under it
    online: { type: "list", entries: names.length ? [{ title: env.get("SERVER_NAME") || "Minecraft", subtitle: playersLine(names), image: ARTWORK }] : [] },
    count: { type: "stat", label: "Players", value: `${names.length}/${max}` },
  };
  return { fields };
}

// Minecraft's key art, from Aaron (2026-11-02), as on the Java card: 660x260, WebP at quality 78.
export const ARTWORK =
  "data:image/webp;base64,";
